syntax:
// declare the type (above main), note the semicolon
struct Student {
    int id;
    string name;
    double cgpa;
};

int main() {
    Student s1;                          // variable (members empty)
    s1.id = 101;                         // dot operator
    Student s2 = {102, "Bilal", 3.2};   // braces, in member order
    cin >> s1.name >> s1.cgpa;           // input into members
    s2 = s1;                             // copy ALL members
    cout << s2.name << endl;             // print one member
    return 0;
}

sample.code:
#include <iostream>
#include <string>
using namespace std;

struct Student {
    int id;
    string name;
    double cgpa;
};

int main() {
    Student s1;
    s1.id = 101;
    s1.name = "Ayesha";
    s1.cgpa = 3.7;
    cout << s1.id << " " << s1.name << " " << s1.cgpa << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Student {
    int id;
    string name;
    double cgpa;
};

int main() {
    Student s1 = {1, "Ali", 3.5};
    Student s2 = s1;
    s2.id = 2;
    s2.name = "Sana";
    cout << s1.id << " " << s1.name << " " << s1.cgpa << endl;
    cout << s2.id << " " << s2.name << " " << s2.cgpa << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Employee {
    int empId;
    string name;
    double salary;
};

int main() {
    Employee e;
    cout << "Enter id, name and salary: ";
    cin >> e.empId >> e.name >> e.salary;
    e.salary = e.salary + e.salary * 0.10;
    cout << "Employee " << e.empId << " (" << e.name << ") now earns " << e.salary << endl;
    return 0;
}

